                { num:16, title:"Interactive Audit Report (in-app)", duration:"Week 15-16", tags:["Growth"], items:["In-browser interactive report with annotated page screenshot (click to zoom issues)", "Fix checklist with progress tracking: check off items as they are implemented", "Severity color coding: red (critical), amber (important), green (nice-to-have) annotations on screenshot", "Share link generation: shareable read-only report link for stakeholders", "Comment threads per recommendation: team discussion on each fix inline", "Export to Jira/Linear as tasks: one-click issue creation for dev team"] },
                { num:17, title:"Mobile-Native Companion App", duration:"Week 16-18", tags:["Moat"], items:["iOS + Android: URL scanner with push notifications for new competitor changes", "Barcode scan mode: scan QR code on printed marketing materials to audit linked landing page", "Offline report viewing: downloaded audits viewable without internet connection", "Share sheet integration: audit any URL from iOS Share Sheet in other apps", "Face ID/Touch ID: biometric login for agency users with sensitive client data", "App Store optimization: target keyword 'landing page analyzer' + 'CRO tool' in 10 countries"] },
                { num:18, title:"Analytics + Admin Dashboard", duration:"Week 17-18", tags:["Core"], items:["Operator dashboard: revenue, churn, activation rate, most-audited industries, top features used", "Cohort analysis: retention by acquisition channel, plan type, industry vertical", "Support ticket integration: Intercom/Crisp with audit context auto-attached to tickets", "Feature flag system: gradual rollout of new audit checks without deployment risk", "A/B test on pricing page: test $29 vs $39 vs $49 Starter price points with randomized allocation", "Revenue analytics: Stripe integration showing MRR, ARR, churn MRR, expansion MRR by plan"] },
                { num:19, title:"Internationalization + Compliance", duration:"Week 18-20", tags:["Growth","Moat"], items:["Multi-language report output: English, Spanish, French, German, Portuguese (covering US/EU/LATAM)", "GDPR-compliant scraping: audit URL data retained max 30 days unless opted in, right to delete", "CCPA compliance for US users: data deletion flow in account settings", "EU VAT handling via Stripe Tax: automatic tax collection for EU business customers", "Cookie consent tool integration: detect and flag missing GDPR consent banners as CRO issue", "Localization of copy benchmarks: UK/AU/CA marketplaces have different trust signal norms"] },
              ].map(p => <Phase key={p.num} {...p} />)}
            </div>
          )}

          {/* ââââââââââââââââââââââ MONEY TAB ââââââââââââââââââââââââ */}
          {tab === "Money" && (
            <div>
              <MRRChart />
              <div style={{ marginTop: 28 }}>
                <PricingSection />
              </div>

              <div style={{ display: "grid", gridTemplateColumns: "1fr 1fr", gap: 20, marginTop: 28 }}>
                {/* Unit Economics */}
                <div style={{ background: D.card, border: `1px solid ${D.border}`, borderRadius: 14, padding: 24 }}>
                  <h3 style={{ margin: "0 0 14px 0", fontSize: 16, fontWeight: 800, color: D.slate1 }}>Unit Economics [assumption]</h3>
                  {[
                    ["Blended ARPU", "$59/mo", "40% StarterÃ$29 + 35% GrowthÃ$49 + 20% ProÃ$99 + 5% AgencyÃ$199"],
                    ["Monthly Churn Rate", "3.5%", "Mid-range for SMB vertical SaaS"],
                    ["Avg Customer LTV", "~$1,686", "ARPU Ã· churn = $59 Ã· 0.035 = 28.6 months Ã $59"],
                    ["CAC (content marketing)", "~$280", "Estimated: content + PH launch + referral program cost per acquired user"],
                    ["LTV:CAC Ratio", "6.0x", "$1,686 Ã· $280 â strong for SMB SaaS"],
                    ["AI API Cost per Audit", "~$0.003", "Claude API ~4K tokens Ã $0.60/M input = $0.0024/audit [assumption]"],
                    ["Gross Margin", "~88%", "Revenue minus AI API + hosting + Stripe (2.9%+$0.30) [assumption]"],
                    ["Stripe Processing", "2.9% + $0.30", "Per transaction; ~$2.01 on $59 charge"],
                  ].map(([k, v, n]) => (
                    <div key={k} style={{ display: "flex", justifyContent: "space-between", alignItems: "flex-start", padding: "9px 0", borderBottom: `1px solid ${D.border}`, gap: 8 }}>
                      <span style={{ fontSize: 13, color: D.slate2 }}>{k}</span>
                      <div style={{ textAlign: "right" }}>
                        <span style={{ fontSize: 14, fontWeight: 700, color: D.purple }}>{v}</span>
