import { useLocation, Link } from "react-router-dom";
import { LayoutDashboard, ScanLine, FileText, Puzzle, Settings, Zap } from "lucide-react";
import { NavLink } from "@/components/NavLink";
import { Badge } from "@/components/ui/badge";
import { Progress } from "@/components/ui/progress";
import {
  Sidebar,
  SidebarContent,
  SidebarGroup,
  SidebarGroupContent,
  SidebarMenu,
  SidebarMenuButton,
  SidebarMenuItem,
  SidebarFooter,
  SidebarHeader,
  useSidebar,
} from "@/components/ui/sidebar";
import { Separator } from "@/components/ui/separator";
import { useAuth } from "@/contexts/AuthContext";
import { useFeatureFlag } from "@/hooks/use-feature-flag";
import { cn } from "@/lib/utils";

interface NavItem {
  title: string;
  url: string;
  icon: React.ElementType;
  flagKey?: string;
}

const BASE_NAV_ITEMS: NavItem[] = [
  { title: "Dashboard", url: "/dashboard", icon: LayoutDashboard },
  { title: "New Scan", url: "/scan", icon: ScanLine },
  { title: "My Reports", url: "/reports", icon: FileText },
  { title: "Integrations", url: "/integrations", icon: Puzzle, flagKey: "integrations_enabled" },
  { title: "Settings", url: "/settings", icon: Settings },
];

export function AppSidebar() {
  const { state } = useSidebar();
  const collapsed = state === "collapsed";
  const location = useLocation();
  const { profile } = useAuth();

  const integrationsEnabled = useFeatureFlag("integrations_enabled", true);

  const navItems = BASE_NAV_ITEMS.filter((item) => {
    if (item.flagKey === "integrations_enabled") return integrationsEnabled;
    return true;
  });

  const scansUsed = profile?.scans_used ?? 0;
  const scanLimit = profile?.scan_limit ?? 3;
  const usagePercent = Math.round((scansUsed / scanLimit) * 100);

  const isActive = (path: string) =>
    location.pathname === path || location.pathname.startsWith(path + "/");

  return (
    <Sidebar collapsible="icon" className="border-r-0">
      <SidebarHeader className="px-4 py-5 group-data-[collapsible=icon]:px-2 group-data-[collapsible=icon]:py-4 group-data-[collapsible=icon]:items-center">
        <Link to="/dashboard" className="flex items-center gap-2.5 group-data-[collapsible=icon]:justify-center group-data-[collapsible=icon]:w-full">
          <div className="flex h-7 w-7 items-center justify-center rounded-lg bg-sidebar-primary shrink-0">
            <ScanLine className="h-3.5 w-3.5 text-white" />
          </div>
          {!collapsed && (
            <span className="text-base font-semibold tracking-tight text-white">
              ConvertScan
            </span>
          )}
        </Link>
      </SidebarHeader>

      <SidebarContent className="px-2 group-data-[collapsible=icon]:px-1">
        <SidebarGroup>
          <SidebarGroupContent>
            <SidebarMenu className="space-y-0.5">
              {navItems.map((item) => {
                const active = isActive(item.url);
                return (
                  <SidebarMenuItem key={item.title}>
                    <SidebarMenuButton
                      asChild
                      tooltip={item.title}
                      isActive={active}
                      className={cn(
                        "h-10 transition-colors duration-150 relative",
                        active
                          ? "bg-white/10 text-white before:absolute before:left-0 before:top-2 before:bottom-2 before:w-[2px] before:rounded-full before:bg-primary"
                          : "text-sidebar-foreground hover:bg-white/5 hover:text-white/80"
                      )}
                    >
                      <NavLink to={item.url} activeClassName="">
                        <item.icon className={cn(
                          "h-[18px] w-[18px] shrink-0",
                          active ? "text-white" : "text-white/55"
                        )} />
                        <span className="text-sm font-medium">{item.title}</span>
                      </NavLink>
                    </SidebarMenuButton>
                  </SidebarMenuItem>
                );
              })}
            </SidebarMenu>
          </SidebarGroupContent>
        </SidebarGroup>
      </SidebarContent>

      <SidebarFooter className="p-3 group-data-[collapsible=icon]:p-2 group-data-[collapsible=icon]:items-center">
        {/* Scan usage indicator — expanded only */}
        {!collapsed && (
          <div className="mb-3 rounded-lg bg-white/5 p-3">
            <div className="flex items-center justify-between mb-1.5">
              <span className="text-xs text-white/40">Scans used</span>
              <span className="text-xs font-medium text-white/70 tabular-nums">
                {profile ? `${scansUsed}/${scanLimit}` : "\u2014"}
              </span>
            </div>
            <Progress value={profile ? usagePercent : 0} className="h-1" />
            <div className="mt-1.5">
              <Badge
                variant="outline"
                className="border-white/10 bg-transparent text-2xs text-white/40 capitalize px-1.5 py-0"
              >
                {profile?.plan ?? "free"} plan
              </Badge>
            </div>
          </div>
        )}

        {/* Separator — hidden when collapsed (nothing above it) */}
        {!collapsed && <Separator className="mb-3 bg-white/5" />}

        {profile?.plan !== "agency" && (
          !collapsed ? (
            <Link
              to="/pricing"
              className="flex items-center justify-center gap-2 rounded-lg bg-sidebar-primary px-4 py-2.5 text-sm font-semibold text-white transition-all hover:opacity-90 hover:shadow-lg hover:shadow-sidebar-primary/20"
            >
              <Zap className="h-4 w-4" />
              Upgrade Plan
            </Link>
          ) : (
            <Link
              to="/pricing"
              aria-label="Upgrade Plan"
              className="flex h-9 w-9 items-center justify-center rounded-lg bg-sidebar-primary text-white transition-opacity hover:opacity-90"
            >
              <Zap className="h-4 w-4" />
            </Link>
          )
        )}
      </SidebarFooter>
    </Sidebar>
  );
}

