import { useState } from "react";
import { useNavigate } from "react-router-dom";
import { AnimatePresence, motion } from "framer-motion";
import { ScanLine, Check, X } from "lucide-react";
import {
  Dialog,
  DialogContent,
  DialogHeader,
  DialogTitle,
  DialogDescription,
} from "@/components/ui/dialog";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { cn } from "@/lib/utils";
import { PAGE_TYPES } from "@/lib/constants";
import { StepIndicator } from "./StepIndicator";
import type { PageType } from "@/types";

// ── Step animation variants ───────────────────────────────────

const stepVariants = {
  enter: (direction: number) => ({
    x: direction > 0 ? 40 : -40,
    opacity: 0,
  }),
  center: {
    x: 0,
    opacity: 1,
  },
  exit: (direction: number) => ({
    x: direction > 0 ? -40 : 40,
    opacity: 0,
  }),
};

// ── Benefit bullets for step 1 ────────────────────────────────

const BENEFITS = [
  "AI-powered CRO analysis across 7 pillars",
  "Specific, actionable fix recommendations",
  "Score your page 0-100 with industry benchmarks",
];

// ── URL validation helper ─────────────────────────────────────

function isValidUrl(value: string): boolean {
  if (!value.trim()) return false;
  try {
    const normalized = /^https?:\/\//i.test(value.trim())
      ? value.trim()
      : `https://${value.trim()}`;
    const url = new URL(normalized);
    return url.protocol === "https:" || url.protocol === "http:";
  } catch {
    return false;
  }
}

function normalizeUrl(value: string): string {
  const trimmed = value.trim();
  if (/^https?:\/\//i.test(trimmed)) return trimmed;
  return `https://${trimmed}`;
}

// ── Props ─────────────────────────────────────────────────────

interface OnboardingModalProps {
  open: boolean;
  onComplete: () => void;
}

// ── Component ─────────────────────────────────────────────────

export function OnboardingModal({ open, onComplete }: OnboardingModalProps) {
  const navigate = useNavigate();
  const [step, setStep] = useState(1);
  const [direction, setDirection] = useState(1);
  const [url, setUrl] = useState("");
  const [selectedPageType, setSelectedPageType] = useState<PageType>("landing");

  const urlValid = isValidUrl(url);

  function goToStep(next: number) {
    setDirection(next > step ? 1 : -1);
    setStep(next);
  }

  function handleDismiss() {
    onComplete();
  }

  function handleStartAudit() {
    onComplete();
    const normalized = normalizeUrl(url);
    navigate(
      `/scan?url=${encodeURIComponent(normalized)}&type=${selectedPageType}`
    );
  }

  return (
    <Dialog open={open} onOpenChange={(isOpen) => { if (!isOpen) handleDismiss(); }}>
      <DialogContent
        className="max-w-lg w-full p-0 overflow-hidden gap-0"
        // hide default close button — we render our own
        onPointerDownOutside={(e) => e.preventDefault()}
      >
        {/* Custom close button */}
        <button
          onClick={handleDismiss}
          className="absolute right-4 top-4 z-10 rounded-sm opacity-70 ring-offset-background transition-opacity hover:opacity-100 focus:outline-none focus:ring-2 focus:ring-ring focus:ring-offset-2"
          aria-label="Close onboarding"
        >
          <X className="h-4 w-4" />
        </button>

        {/* Header bar with step indicator */}
        <div className="px-6 pt-6 pb-4 border-b border-border/50">
          <StepIndicator currentStep={step} totalSteps={3} />
        </div>

        {/* Animated step content */}
        <div className="relative overflow-hidden">
          <AnimatePresence initial={false} custom={direction} mode="wait">
            {step === 1 && (
              <motion.div
                key="step-1"
                custom={direction}
                variants={stepVariants}
                initial="enter"
                animate="center"
                exit="exit"
                transition={{ duration: 0.22, ease: "easeInOut" }}
                className="px-6 pt-6 pb-7 space-y-5"
              >
                {/* Icon */}
                <div className="flex justify-center">
                  <div className="flex h-16 w-16 items-center justify-center rounded-2xl bg-primary/10">
                    <ScanLine className="h-8 w-8 text-primary" />
                  </div>
                </div>

                {/* Heading */}
                <DialogHeader className="text-center space-y-1.5">
                  <DialogTitle className="text-xl font-bold tracking-tight">
                    Welcome to ConvertScan
                  </DialogTitle>
                  <DialogDescription className="text-sm text-muted-foreground">
                    Let's run your first CRO audit in 60 seconds
                  </DialogDescription>
                </DialogHeader>

                {/* Benefits */}
                <ul className="space-y-2.5">
                  {BENEFITS.map((benefit) => (
                    <li key={benefit} className="flex items-start gap-3">
                      <div className="mt-0.5 flex h-5 w-5 shrink-0 items-center justify-center rounded-full bg-emerald-500/10">
                        <Check className="h-3 w-3 text-emerald-600" />
                      </div>
                      <span className="text-sm text-foreground leading-snug">
                        {benefit}
                      </span>
                    </li>
                  ))}
                </ul>

                <Button
                  className="w-full h-11 font-semibold rounded-xl"
                  onClick={() => goToStep(2)}
                >
                  Let's Go
                </Button>
              </motion.div>
            )}

            {step === 2 && (
              <motion.div
                key="step-2"
                custom={direction}
                variants={stepVariants}
                initial="enter"
                animate="center"
                exit="exit"
                transition={{ duration: 0.22, ease: "easeInOut" }}
                className="px-6 pt-6 pb-7 space-y-5"
              >
                <DialogHeader className="space-y-1.5">
                  <DialogTitle className="text-xl font-bold tracking-tight">
                    Paste your first URL
                  </DialogTitle>
                  <DialogDescription className="text-sm text-muted-foreground">
                    We'll take a screenshot and run 80+ CRO checks
                  </DialogDescription>
                </DialogHeader>

                <div className="space-y-2">
                  <Input
                    type="url"
                    placeholder="https://your-website.com/landing-page"
                    value={url}
                    onChange={(e) => setUrl(e.target.value)}
                    className={cn(
                      "h-11 rounded-xl border-border/50 bg-background text-sm",
                      "focus-visible:ring-primary/20 focus-visible:border-primary",
                      url && !urlValid && "border-red-400 focus-visible:border-red-400 focus-visible:ring-red-200"
                    )}
                    autoFocus
                    onKeyDown={(e) => {
                      if (e.key === "Enter" && urlValid) goToStep(3);
                    }}
                  />
                  {url && !urlValid && (
                    <p className="text-xs text-red-500">
                      Please enter a valid URL (e.g. https://yoursite.com)
                    </p>
                  )}
                </div>

                <div className="flex gap-2">
                  <Button
                    variant="outline"
                    className="flex-1 h-11 rounded-xl"
                    onClick={() => goToStep(1)}
                  >
                    Back
                  </Button>
                  <Button
                    className="flex-1 h-11 font-semibold rounded-xl"
                    disabled={!urlValid}
                    onClick={() => goToStep(3)}
                  >
                    Next
                  </Button>
                </div>
              </motion.div>
            )}

            {step === 3 && (
              <motion.div
                key="step-3"
                custom={direction}
                variants={stepVariants}
                initial="enter"
                animate="center"
                exit="exit"
                transition={{ duration: 0.22, ease: "easeInOut" }}
                className="px-6 pt-6 pb-7 space-y-5"
              >
                <DialogHeader className="space-y-1.5">
                  <DialogTitle className="text-xl font-bold tracking-tight">
                    What type of page is this?
                  </DialogTitle>
                  <DialogDescription className="text-sm text-muted-foreground">
                    We'll tailor the audit weights for your page type
                  </DialogDescription>
                </DialogHeader>

                {/* Page type grid */}
                <div className="grid grid-cols-2 gap-2">
                  {PAGE_TYPES.map((pt) => (
                    <button
                      key={pt.value}
                      type="button"
                      onClick={() => setSelectedPageType(pt.value as PageType)}
                      className={cn(
                        "rounded-xl border px-4 py-3 text-sm font-medium text-left transition-all duration-150",
                        "focus:outline-none focus-visible:ring-2 focus-visible:ring-primary/50",
                        selectedPageType === pt.value
                          ? "border-primary bg-primary/8 text-primary"
                          : "border-border/60 bg-background text-foreground hover:border-primary/40 hover:bg-muted/40"
                      )}
                    >
                      {pt.label}
                    </button>
                  ))}
                </div>

                <div className="flex gap-2">
                  <Button
                    variant="outline"
                    className="flex-1 h-11 rounded-xl"
                    onClick={() => goToStep(2)}
                  >
                    Back
                  </Button>
                  <Button
                    className="flex-1 h-11 font-semibold rounded-xl"
                    onClick={handleStartAudit}
                  >
                    Start Audit
                  </Button>
                </div>
              </motion.div>
            )}
          </AnimatePresence>
        </div>
      </DialogContent>
    </Dialog>
  );
}

