export function useUpdateFindingStatus() {
  return useMutation({
    mutationFn: async (payload) => {
      // Insert or update finding_tracker row
      const { data: existing } = await supabase
        .from("finding_tracker")
        .select("*")
        .eq("scan_id", payload.scan_id)
        .eq("finding_id", payload.finding_id)
        .single();

      if (existing) {
        return supabase.from("finding_tracker")
          .update({ status: payload.status, notes: payload.notes, updated_at: new Date().toISOString() })
          .eq("id", existing.id);
      } else {
        return supabase.from("finding_tracker").insert(payload);
      }
    },
  });
}
```

