export function useFindingStatuses(scanId: string) {
  return useQuery({
    queryKey: ["finding-statuses", scanId],
    queryFn: async () => {
      const { data } = await supabase
        .from("finding_tracker")
        .select("*")
        .eq("scan_id", scanId);
      return data;
    },
  });
