  id: string;
  user_id: string;
  team_id?: string;
  status: "pending" | "running" | "completed" | "failed";
  urls: string[];                       // CSV or JSON array
  total: number;
  completed: number;
  failed: number;
  created_at: string;
}

// Webhooks (for Sprint 5)
