  created_at: string;
}
```

---

### **5. SETTINGS PAGE** (`src/pages/Settings.tsx` — first 50 lines)

**Current Tabs Structure:**
```typescript
<Tabs>
  <TabsList>
    <TabsTrigger>Profile</TabsTrigger>
    <TabsTrigger>Billing</TabsTrigger>
    <TabsTrigger>Notifications</TabsTrigger>
    <TabsTrigger>Support</TabsTrigger>
    <TabsTrigger>Account</TabsTrigger>
  </TabsList>
  <TabsContent>...</TabsContent>
  {/* Continues with tab content */}
</Tabs>
```

**Sprint 4/5 Tabs to Add:**
```
<TabsTrigger>API</TabsTrigger>           (Sprint 5)
<TabsTrigger>Webhooks</TabsTrigger>      (Sprint 5)
