        user_id: user.id,
        provider,
        access_token: accessToken,
      });
    },
  });
}
```

---

### **14. FEATURE FLAG PATTERN**

**Current:**
```typescript
const integrationsEnabled = useFeatureFlag("integrations_enabled", true);
```

**For Sprint 4/5:**
```typescript
const bulkScanEnabled = useFeatureFlag("bulk_scan_enabled", false);
const apiEnabled = useFeatureFlag("api_enabled", false);
const slackIntegrationEnabled = useFeatureFlag("slack_integration_enabled", false);
```

These are stored in the `feature_flags` table and checked at render time.

