-- 011_teams.sql
-- Team workspaces, team members, invites, and bulk scan jobs.

-- ── Teams ────────────────────────────────────────────────────────

CREATE TABLE public.teams (
  id           UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  name         TEXT NOT NULL,
  owner_id     UUID NOT NULL REFERENCES public.profiles(id) ON DELETE CASCADE,
  logo_url     TEXT,
  brand_color  TEXT DEFAULT '#5B5FC7',
  custom_domain TEXT,
  created_at   TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

CREATE INDEX idx_teams_owner ON public.teams(owner_id);

-- ── Team Members ─────────────────────────────────────────────────

CREATE TABLE public.team_members (
  id        UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  team_id   UUID NOT NULL REFERENCES public.teams(id) ON DELETE CASCADE,
  user_id   UUID NOT NULL REFERENCES public.profiles(id) ON DELETE CASCADE,
  role      TEXT NOT NULL DEFAULT 'member' CHECK (role IN ('owner', 'admin', 'member')),
  joined_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  UNIQUE(team_id, user_id)
);

CREATE INDEX idx_team_members_user ON public.team_members(user_id);
CREATE INDEX idx_team_members_team ON public.team_members(team_id);

-- ── Team Invites ─────────────────────────────────────────────────

CREATE TABLE public.team_invites (
  id         UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  team_id    UUID NOT NULL REFERENCES public.teams(id) ON DELETE CASCADE,
  email      TEXT NOT NULL,
  role       TEXT NOT NULL DEFAULT 'member',
  token      TEXT NOT NULL UNIQUE,
  expires_at TIMESTAMPTZ NOT NULL DEFAULT NOW() + INTERVAL '7 days',
  created_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

-- ── Team scans (add team_id to scans) ────────────────────────────

ALTER TABLE public.scans ADD COLUMN IF NOT EXISTS team_id UUID REFERENCES public.teams(id) ON DELETE SET NULL;
CREATE INDEX idx_scans_team ON public.scans(team_id) WHERE team_id IS NOT NULL;

-- ── Bulk Scan Jobs ───────────────────────────────────────────────

CREATE TABLE public.bulk_scan_jobs (
  id         UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  user_id    UUID NOT NULL REFERENCES public.profiles(id) ON DELETE CASCADE,
  team_id    UUID REFERENCES public.teams(id) ON DELETE SET NULL,
  status     TEXT NOT NULL DEFAULT 'pending' CHECK (status IN ('pending', 'processing', 'completed', 'failed')),
  urls       TEXT[] NOT NULL,
  page_type  TEXT NOT NULL DEFAULT 'landing',
  total      INTEGER NOT NULL,
  completed  INTEGER NOT NULL DEFAULT 0,
  failed     INTEGER NOT NULL DEFAULT 0,
  created_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

CREATE INDEX idx_bulk_jobs_user ON public.bulk_scan_jobs(user_id);

-- ── RLS Policies ─────────────────────────────────────────────────

ALTER TABLE public.teams ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.team_members ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.team_invites ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.bulk_scan_jobs ENABLE ROW LEVEL SECURITY;

-- Teams: members can read, owners can manage
CREATE POLICY "teams_member_read" ON public.teams
  FOR SELECT USING (
    EXISTS (SELECT 1 FROM public.team_members WHERE team_members.team_id = teams.id AND team_members.user_id = auth.uid())
  );
CREATE POLICY "teams_owner_insert" ON public.teams
  FOR INSERT WITH CHECK (owner_id = auth.uid());
CREATE POLICY "teams_owner_update" ON public.teams
  FOR UPDATE USING (owner_id = auth.uid()) WITH CHECK (owner_id = auth.uid());
CREATE POLICY "teams_owner_delete" ON public.teams
  FOR DELETE USING (owner_id = auth.uid());
CREATE POLICY "teams_admin_read" ON public.teams
  FOR SELECT USING (public.is_admin());

-- Team members: members can read their team's members, owners can manage
CREATE POLICY "team_members_read" ON public.team_members
  FOR SELECT USING (
    EXISTS (SELECT 1 FROM public.team_members tm WHERE tm.team_id = team_members.team_id AND tm.user_id = auth.uid())
  );
CREATE POLICY "team_members_owner_insert" ON public.team_members
  FOR INSERT WITH CHECK (
    EXISTS (SELECT 1 FROM public.teams WHERE teams.id = team_members.team_id AND teams.owner_id = auth.uid())
  );
CREATE POLICY "team_members_owner_update" ON public.team_members
  FOR UPDATE USING (
    EXISTS (SELECT 1 FROM public.teams WHERE teams.id = team_members.team_id AND teams.owner_id = auth.uid())
  );
CREATE POLICY "team_members_owner_delete" ON public.team_members
  FOR DELETE USING (
    EXISTS (SELECT 1 FROM public.teams WHERE teams.id = team_members.team_id AND teams.owner_id = auth.uid())
  );

-- Team invites: owners can manage
CREATE POLICY "team_invites_owner_all" ON public.team_invites
  FOR ALL USING (
    EXISTS (SELECT 1 FROM public.teams WHERE teams.id = team_invites.team_id AND teams.owner_id = auth.uid())
  );

-- Scans: team members can read team scans
CREATE POLICY "scans_team_read" ON public.scans
  FOR SELECT USING (
    team_id IS NOT NULL AND EXISTS (
      SELECT 1 FROM public.team_members WHERE team_members.team_id = scans.team_id AND team_members.user_id = auth.uid()
    )
  );

-- Bulk scan jobs: users can manage their own
CREATE POLICY "bulk_jobs_own" ON public.bulk_scan_jobs
  FOR ALL USING (auth.uid() = user_id) WITH CHECK (auth.uid() = user_id);

